'use client';
import { useId, useMemo, useRef, useState, type KeyboardEvent } from 'react';
import { motion } from 'motion/react';
import { spring, useStudioMotion, type SpringToken } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { tabs: string; shape: string; spring: string; activation: string; ghost: boolean };

/** Sample panel copy, cycled by tab index. */
const BLURBS = [
  'A calm summary of what moved since you last looked, with the noisy parts folded away.',
  'Every change in order, newest first. Nothing is hidden, only grouped.',
  'Who can see this space, and what each of them is able to do in it.',
  'Plan, seats and the next invoice date, kept on one quiet screen.',
  'Fine-grained switches for the things most people never need to touch.',
  'Keys, webhooks and the audit trail for everything automated.',
];

const isSpringToken = (v: string): v is SpringToken => v in spring;

export default function MorphingNavPill({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const tabs = useMemo(() => {
    const t = params.tabs.split(',').map((s) => s.trim()).filter(Boolean).slice(0, 6);
    return t.length ? t : ['Tab'];
  }, [params.tabs]);
  const [selectedRaw, setSelected] = useState(0);
  const [ghostAt, setGhostAt] = useState<number | null>(null);
  const selected = Math.min(selectedRaw, tabs.length - 1);
  const refs = useRef<(HTMLButtonElement | null)[]>([]);

  const shape = params.shape === 'underline' || params.shape === 'block' ? params.shape : 'pill';
  const token: SpringToken = isSpringToken(params.spring) ? params.spring : 'settle';
  const transition = reduced ? { duration: 0 } : { type: 'spring' as const, ...spring[token] };
  const radius = shape === 'pill' ? 999 : shape === 'block' ? 7 : 1;
  const showGhost = params.ghost && !reduced && ghostAt !== null && ghostAt !== selected;

  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
    const last = tabs.length - 1;
    let next: number | null = null;
    if (e.key === 'ArrowRight') next = i === last ? 0 : i + 1;
    else if (e.key === 'ArrowLeft') next = i === 0 ? last : i - 1;
    else if (e.key === 'Home') next = 0;
    else if (e.key === 'End') next = last;
    if (next === null) return;
    e.preventDefault();
    refs.current[next]?.focus();
    if (params.activation !== 'manual') setSelected(next);
  };

  return (
    <div className={styles.root} data-shape={shape} data-reduced={reduced || undefined}>
      <motion.div
        layoutScroll
        role="tablist"
        aria-label="Workspace sections (sample)"
        className={styles.tablist}
        onPointerLeave={() => setGhostAt(null)}
      >
        {tabs.map((label, i) => {
          const active = i === selected;
          return (
            <button
              key={`${label}-${i}`}
              ref={(el) => { refs.current[i] = el; }}
              type="button"
              role="tab"
              id={`${uid}tab${i}`}
              aria-selected={active}
              aria-controls={`${uid}panel${i}`}
              tabIndex={active ? 0 : -1}
              className={styles.tab}
              onClick={() => setSelected(i)}
              onKeyDown={(e) => onKeyDown(e, i)}
              onPointerEnter={(e) => { if (e.pointerType === 'mouse') setGhostAt(i); }}
              onFocus={(e) => { if (e.currentTarget.matches(':focus-visible')) setGhostAt(i); }}
              onBlur={() => setGhostAt(null)}
            >
              {showGhost && ghostAt === i ? (
                <motion.span layoutId={`${uid}ghost`} className={styles.ghost} style={{ borderRadius: radius }} transition={transition} aria-hidden="true" />
              ) : null}
              {active ? (
                <motion.span layoutId={`${uid}indicator`} className={styles.indicator} style={{ borderRadius: radius }} transition={transition} aria-hidden="true" />
              ) : null}
              <span className={styles.tabLabel}>{label}</span>
            </button>
          );
        })}
      </motion.div>

      <div className={styles.panels}>
        {tabs.map((label, i) => {
          const active = i === selected;
          return (
            <div
              key={`${label}-${i}`}
              role="tabpanel"
              id={`${uid}panel${i}`}
              aria-labelledby={`${uid}tab${i}`}
              tabIndex={active ? 0 : -1}
              inert={!active}
              data-active={active || undefined}
              className={styles.panel}
            >
              <p className={styles.index}>{String(i + 1).padStart(2, '0')} / {String(tabs.length).padStart(2, '0')} <span className={styles.sample}>sample content</span></p>
              <h3 className={styles.title}>{label}</h3>
              <p className={styles.copy}>{BLURBS[i % BLURBS.length]}</p>
            </div>
          );
        })}
      </div>
    </div>
  );
}

.root {
  box-sizing: border-box;
  width: min(100% - 2rem, 35rem);
  margin: clamp(1.25rem, 4cqi, 2.5rem) auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(1.25rem, 3.5cqi, 2rem);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
}

/* ── Tab list ─────────────────────────────────────────────────────────── */
.tablist {
  position: relative;
  display: flex;
  gap: 2px;
  padding: 4px;
  overflow-x: auto;
  scrollbar-width: none;
  border-radius: 999px;
  background: var(--s3-surface-2, #e9e5da);
}
.root[data-shape='block'] .tablist { border-radius: 11px; }
.root[data-shape='underline'] .tablist {
  padding: 0;
  gap: clamp(0.25rem, 2cqi, 1rem);
  border-radius: 0;
  background: none;
  box-shadow: inset 0 -1px 0 var(--s3-line, #11110f24);
}
.tab {
  position: relative;
  flex: 1 0 auto;
  min-height: 2.75rem;
  padding: 0 clamp(0.75rem, 3cqi, 1.25rem);
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--s3-ink-muted, #5c5a52);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 500;
  letter-spacing: -0.005em;
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--s3-duration-base, 240ms) var(--s3-ease-standard, ease);
}
.root[data-shape='block'] .tab { border-radius: 7px; }
.root[data-shape='underline'] .tab { flex: 0 0 auto; padding-inline: 0.25rem; border-radius: 2px; }
.tab:hover { color: var(--s3-ink, #11110f); }
.tab[aria-selected='true'] { color: var(--s3-surface, #fbf9f4); }
.root[data-shape='block'] .tab[aria-selected='true'],
.root[data-shape='underline'] .tab[aria-selected='true'] { color: var(--s3-ink, #11110f); }
.tab:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.tabLabel { position: relative; z-index: 1; }

.indicator, .ghost {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.indicator { background: var(--s3-ink, #11110f); }
.ghost { background: color-mix(in oklab, var(--s3-ink, #11110f) 9%, transparent); }
.root[data-shape='block'] .indicator {
  background: var(--s3-surface, #fbf9f4);
  box-shadow: 0 0 0 1px var(--s3-line, #11110f24), 0 1px 2px rgb(0 0 0 / 0.08);
}
.root[data-shape='underline'] .indicator { inset: auto 0 0 0; height: 2px; background: var(--s3-signal, #bf2f09); }
.root[data-shape='underline'] .ghost { inset: auto 0 0 0; height: 2px; background: var(--s3-line-strong, #11110f); opacity: 0.35; }

/* ── Panels: one grid cell, tallest panel wins, no layout shift ───────── */
.panels { display: grid; }
.panel {
  grid-area: 1 / 1;
  display: grid;
  align-content: start;
  gap: 0.6rem;
  padding: clamp(1.1rem, 4cqi, 1.75rem);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: var(--s3-radius-l, 18px);
  opacity: 0;
  visibility: hidden;
  transform: translateY(6px);
  transition:
    opacity var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease),
    transform 0s linear var(--s3-duration-fast, 160ms),
    visibility 0s linear var(--s3-duration-fast, 160ms);
}
.panel[data-active] {
  opacity: 1;
  visibility: visible;
  transform: none;
  transition:
    opacity var(--s3-duration-moderate, 360ms) var(--s3-ease-standard, ease) 60ms,
    transform var(--s3-duration-moderate, 360ms) var(--s3-ease-emphasized, ease) 60ms,
    visibility 0s;
}
.root[data-reduced] .panel { transform: none; transition: opacity 160ms linear, visibility 0s linear 160ms; }
.root[data-reduced] .panel[data-active] { transition: opacity 160ms linear, visibility 0s; }
.panel:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 3px; }
.index {
  margin: 0;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--s3-ink-muted, #5c5a52);
}
.sample { color: var(--s3-ink-muted, #5c5a52); }
.title {
  margin: 0.5rem 0 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.5rem, 6cqi, 2.25rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
}
.copy {
  margin: 0;
  max-width: 38ch;
  min-height: 3lh;
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--s3-ink-muted, #5c5a52);
  text-wrap: pretty;
}
